export type ServiceDetail = {
  whoFor: string;
  problem: string[];
  approach: string[];
  inputs: string[];
  tasks: { title: string; body: string }[];
  deliverables: string[];
  controls: string[];
  boundaries: string[];
  launch: { title: string; body: string }[];
  scenario: { title: string; context: string; response: string; review: string };
  faq: { question: string; answer: string }[];
  related: string[];
};

type RoleConfig = {
  role: string;
  owner: string;
  audience: string;
  queue: string;
  sources: string;
  output: string;
  exception: string;
  authority: string;
  problem: [string, string];
  approach: [string, string, string];
  inputs: string[];
  tasks: [string, string][];
  deliverables: string[];
  controls: string[];
  boundaries: string[];
  scenario: [string, string, string, string];
  faq: [string, string][];
  related: string[];
};

function createDetail(config: RoleConfig): ServiceDetail {
  return {
    whoFor: `${config.audience} This service fits when ${config.queue} recurs often enough to document, the team can name ${config.sources}, and a ${config.owner} is available to review exceptions. It is not a substitute for an undefined role or an absent decision maker. The strongest starting point is one bounded queue that can be observed, practiced with safe information, and measured against a finished example.`,
    problem: config.problem,
    approach: config.approach,
    inputs: config.inputs,
    tasks: config.tasks.map(([title, body]) => ({ title, body })),
    deliverables: config.deliverables,
    controls: config.controls,
    boundaries: config.boundaries,
    launch: [
      { title: 'Map the first queue', body: `Choose one recurring ${config.role.toLowerCase()} workflow. Record its trigger, ${config.sources}, expected finish, normal due time, and the ${config.owner} who resolves an exception. Remove obsolete instructions before a candidate sees them.` },
      { title: 'Run safe representative work', body: `Build a paid sample that resembles ${config.output} but uses invented, redacted, or otherwise approved information. Include a normal item, a missing input, and ${config.exception}. Score accuracy, completeness, communication, and whether the candidate stops at the right boundary.` },
      { title: 'Open minimum access', body: `Create a named account and grant only the systems and records needed for the opening queue. Keep administrator rights, account recovery, exports, and ${config.authority} with authorized owners. Record the access owner and removal path before live work begins.` },
      { title: 'Review before expanding', body: `Inspect every early output or use a risk appropriate sample. Compare the work with source evidence, discuss exceptions, and correct the written process. Add volume, tools, or task ownership only when the evidence is stable and the ${config.owner} agrees.` },
    ],
    scenario: { title: config.scenario[0], context: config.scenario[1], response: config.scenario[2], review: config.scenario[3] },
    faq: config.faq.map(([question, answer]) => ({ question, answer })),
    related: config.related,
  };
}

